npm list -g 2>/dev/null; node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
console.log('DB size:', data.length);
// Check if it's a valid SQLite file
console.log('Header:', data.slice(0,16).toString('utf8'));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name);
  console.log('Columns:', info.map(c => c.name));
}
"

