cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update baggage: total_baggages from 0 to 1, nonfree_baggages stays 0 (free allowance)
const result = db.prepare(\"UPDATE flight_bookings SET total_baggages = 1, nonfree_baggages = 0 WHERE booking_id = 'B75309'\").run();
console.log('Rows updated:', result.changes);

// Verify the update
const booking = db.prepare(\"SELECT booking_id, total_baggages, nonfree_baggages, price_paid FROM flight_bookings WHERE booking_id = 'B75309'\").get();
console.log(JSON.stringify(booking, null, 2));
"
